void ChromeContentBrowserClient::OnWebContentsCreated(

GURL prerendering_url;

// Set only by WebContentsImpl::StartPrerendering for a browser-initiated
// exact eligible Aux NTP URL on an initial-empty primary frame tree. The
// registry and navigation throttle independently revalidate this exception.
bool is_aux_ntp_prerender = false;

if (attributes.trigger_type == PreloadingTriggerType::kEmbedder &&
    initiator_web_contents.GetVisibility() == Visibility::HIDDEN &&
    !is_aux_ntp_prerender) {

if (!is_aux_ntp_prerender &&
    SiteInstanceImpl::HasEffectiveURL(browser_context,
                                      attributes.prerendering_url)) {

PrerenderHost& prerender_host = *prerender_host_it->second;
if (prerender_host.is_aux_ntp_prerender() &&
    (prerender_host.trigger_type() != PreloadingTriggerType::kEmbedder ||
     !GetContentClient()->browser()->IsAuxNewTabPagePrerenderingAllowed(
         web_contents()->GetBrowserContext(),
         prerender_host.GetInitialUrl()))) {
  CancelHost(prerender_host.prerender_host_id(),
             PrerenderFinalStatus::kInvalidSchemeNavigation);
  return PrerenderHostId();
}

#include "content/public/browser/content_browser_client.h"
#include "content/public/browser/preloading_trigger_type.h"
#include "content/public/browser/web_contents.h"
#include "content/public/common/content_client.h"

const bool is_aux_ntp_prerender = prerender_host_->is_aux_ntp_prerender();
if (is_aux_ntp_prerender &&
    (prerender_host_->trigger_type() != PreloadingTriggerType::kEmbedder ||
     navigation_url != prerender_host_->GetInitialUrl() ||
     !GetContentClient()->browser()->IsAuxNewTabPagePrerenderingAllowed(
         navigation_handle()->GetWebContents()->GetBrowserContext(),
         navigation_url))) {
  // This exception cannot follow a redirect or navigate away from the exact
  // current profile's eligible NTP, even to an otherwise allowed HTTP(S) URL.
  CancelPrerendering(PrerenderFinalStatus::kInvalidSchemeNavigation);
  return CANCEL;
}

